#include <atomic>
#include <thread>
#include <vector>

int countTogether(int threads, int perThread)
{
    std::atomic<int> total{ 0 };
    {
        std::vector<std::jthread> workers{};
        for (int t{ 0 }; t < threads; ++t)
        {
            workers.emplace_back([&total, perThread] { for (int i{ 0 }; i < perThread; ++i) ++total; });
        }
    }
    return total.load();
}
